mapper.select:
SELECT sbu.*, u.nickname nickname, u.avatar avatar FROM eb_store_bargain_user AS sbu left join eb_user u on u.uid = sbu.uid
sbu.is_del = 0
and sbu.status = #{status}
and sbu.add_time between #{startTime} and #{endTime}
and ( u.uid like CONCAT('%',#{keywords},'%') or u.nickname like CONCAT('%',#{keywords},'%') or u.phone like CONCAT('%',#{keywords},'%') )
and u.uid = #{uid}
and u.nickname like CONCAT('%',#{nickname},'%')
and u.phone like CONCAT('%',#{phone},'%')
ORDER BY sbu.id desc
